export const CORE_PACK_YAML = "# Rule pack `core` 0.1.0: the 23 deterministic rules of docs/08, written against the extended\n# match kinds of ADR-15. Patterns are RE2, lowercase, and use `(?P<span>...)` to mark the span.\n# Examples written as <eval corpus ref: ...> describe a whole document; Phase 2 authors those\n# corpus files, and the engine verifies every example (each hit must fire, each miss must not).\nschema: prosegate.rulepack/1\nid: core\nversion: 0.1.0\nfindings_schema: 1\nrules:\n  # ---- filler -------------------------------------------------------------------------------\n  - id: core.filler.001\n    category: filler\n    severity: block\n    match:\n      kind: phrase\n      position: sentence_start\n      phrases:\n        - \"let's dive in\"\n        - \"let's dive into\"\n        - \"let's explore\"\n        - \"great question\"\n        - \"certainly!\"\n        - \"absolutely!\"\n        - \"sure thing\"\n        - \"i'd be happy to\"\n        - \"i'd be glad to\"\n    instruction: { action: remove, text: \"Remove. Start with the answer.\" }\n    examples:\n      hit: [\"Great question! Let's dive into the cache layer.\"]\n      miss: [\"The cache layer is per tenant.\"]\n\n  - id: core.filler.002\n    category: filler\n    severity: block\n    match:\n      kind: phrase\n      position: closing\n      phrases:\n        - \"i hope this helps\"\n        - \"hope this helps\"\n        - \"feel free to reach out\"\n        - \"let me know if you have any questions\"\n        - \"happy to help\"\n        - \"don't hesitate to\"\n    instruction: { action: remove, text: \"Remove. End on the last substantive point.\" }\n    examples:\n      hit: [\"Let me know if you have any questions!\"]\n      miss: [\"Reply by Thursday if the dates don't work.\"]\n\n  - id: core.filler.003\n    category: filler\n    severity: block\n    match:\n      kind: phrase\n      phrases:\n        - \"as an ai\"\n        - \"as a language model\"\n        - \"this document outlines\"\n        - \"in this section we will\"\n        - \"in this response\"\n        - \"the following is\"\n    instruction: { action: remove, text: \"Remove the meta-commentary; state the content directly.\" }\n    examples:\n      hit: [\"This document outlines the migration plan.\"]\n      miss: [\"The migration runs in three phases.\"]\n\n  - id: core.filler.004\n    category: filler\n    severity: warn\n    match:\n      kind: phrase\n      position: sentence_start\n      max_doc_words: 399\n      phrases:\n        - \"in conclusion\"\n        - \"to summarize\"\n        - \"in summary\"\n        - \"overall,\"\n    instruction: { action: remove, text: \"Remove; a reply this short needs no summary.\" }\n    examples:\n      hit: [\"In summary, the fix is safe.\"]\n      miss: [\"<eval corpus ref: core/filler-004-miss-01>\"]\n\n  # ---- hedge --------------------------------------------------------------------------------\n  - id: core.hedge.001\n    category: hedge\n    severity: block\n    match:\n      kind: any\n      parts:\n        - kind: regex\n          pattern: '\\b(?:it''s|it is) (?:important to note|worth noting|worth mentioning)(?: that)?,?'\n        - kind: regex\n          pattern: '\\bit should be noted(?: that)?,?'\n        - kind: phrase\n          phrases: [\"note that\"]\n          position: sentence_start\n    instruction: { action: remove, text: \"Remove the preamble; keep the clause after it.\" }\n    examples:\n      hit: [\"It's worth noting that the index is unique.\"]\n      miss: [\"The index is unique.\"]\n\n  - id: core.hedge.002\n    category: hedge\n    severity: warn\n    match:\n      kind: regex\n      pattern: '\\b(?P<span>somewhat|fairly|relatively)\\s+[a-z]+'\n    instruction: { action: specify, text: \"Replace the qualifier with the measurement or the plain adjective.\" }\n    examples:\n      hit: [\"The query is relatively slow.\"]\n      miss: [\"The query takes 400 ms.\"]\n\n  - id: core.hedge.003\n    category: hedge\n    severity: warn\n    match:\n      kind: phrase\n      phrases:\n        - \"arguably\"\n        - \"generally speaking\"\n        - \"in many cases\"\n        - \"it could be argued\"\n        - \"to some extent\"\n        - \"in a sense\"\n    instruction: { action: remove, text: \"Remove the hedge or state who argues it and why.\" }\n    examples:\n      hit: [\"Arguably, the retry is unnecessary.\"]\n      miss: [\"The retry is unnecessary.\"]\n\n  - id: core.hedge.004\n    category: hedge\n    severity: block\n    match:\n      kind: regex\n      pattern: '\\b(may or may not|could potentially|might possibly|can possibly)\\b'\n    instruction: { action: replace, text: \"Pick one: say whether it does, and under what condition.\" }\n    examples:\n      hit: [\"This could potentially break the build.\"]\n      miss: [\"This breaks the build when X.\"]\n\n  - id: core.hedge.005\n    category: hedge\n    severity: warn\n    match:\n      kind: regex\n      pattern: '\\bit depends[.!]'\n    instruction: { action: specify, text: \"Say what it depends on, in the same sentence.\" }\n    examples:\n      hit: [\"It depends.\"]\n      miss: [\"It depends on whether the table is partitioned.\"]\n\n  # ---- vocab --------------------------------------------------------------------------------\n  - id: core.vocab.001\n    category: vocab\n    severity: warn\n    match:\n      kind: any\n      parts:\n        - kind: phrase\n          phrases:\n            - delve\n            - delves\n            - delved\n            - delving\n            - leverages\n            - leveraged\n            - leveraging\n            - utilize\n            - utilizes\n            - utilized\n            - utilizing\n            - utilise\n            - utilises\n            - utilised\n            - utilising\n            - foster\n            - fosters\n            - fostered\n            - fostering\n            - streamline\n            - streamlines\n            - streamlined\n            - streamlining\n            - bolster\n            - bolsters\n            - bolstered\n            - elevate\n            - elevates\n            - elevated\n            - elevating\n        - kind: regex\n          pattern: '\\b(?:to|can|could|should|will|would|we|you|they|i|us) (?P<span>leverage)\\b'\n        - kind: regex\n          pattern: '\\b(?P<span>underscore[sd]) (?:the|that|how|why|a|an|our|its|this)\\b'\n    instruction: { action: replace, text: \"Use the plain verb (use, build, support, speed up).\" }\n    examples:\n      hit: [\"We can leverage the existing cache.\"]\n      miss: [\"We can use the existing cache.\"]\n\n  - id: core.vocab.002\n    category: vocab\n    severity: warn\n    match:\n      kind: any\n      parts:\n        - kind: phrase\n          phrases: [tapestry, realm, testament, synergy, \"paradigm shift\", game-changer, cornerstone]\n        - kind: regex\n          pattern: '\\b(?:the|this|today''s) (?:current |modern |evolving |changing )?landscape\\b'\n    instruction: { action: replace, text: \"Name the concrete thing instead of the abstraction.\" }\n    examples:\n      hit: [\"The current landscape of auth libraries…\"]\n      miss: [\"Three auth libraries fit: …\"]\n\n  - id: core.vocab.003\n    category: vocab\n    severity: warn\n    match:\n      kind: phrase\n      phrases:\n        - robust\n        - seamless\n        - seamlessly\n        - crucial\n        - pivotal\n        - nuanced\n        - holistic\n        - cutting-edge\n        - comprehensive\n        - meticulous\n        - ever-evolving\n    instruction: { action: specify, text: \"Replace with the property that makes it so, or remove.\" }\n    examples:\n      hit: [\"A robust and seamless integration.\"]\n      miss: [\"The integration retries on 5xx and is idempotent.\"]\n\n  - id: core.vocab.004\n    category: vocab\n    severity: warn\n    match:\n      kind: any\n      parts:\n        - kind: phrase\n          phrases: [truly, genuinely, incredibly, remarkably, extremely]\n        - kind: regex\n          pattern: '\\b(?P<span>highly) (?:effective|efficient|scalable|recommended|likely|unlikely)\\b'\n    instruction: { action: remove, text: \"Remove the intensifier.\" }\n    examples:\n      hit: [\"This is incredibly useful.\"]\n      miss: [\"This saves 20 minutes per deploy.\"]\n\n  - id: core.vocab.005\n    category: vocab\n    severity: warn\n    match:\n      kind: phrase\n      phrases: [\"a wide range of\", \"a variety of\", \"a plethora of\", \"a myriad of\", \"a number of\", \"various\"]\n    instruction: { action: specify, text: \"Give the count or the items.\" }\n    examples:\n      hit: [\"There are a number of options.\"]\n      miss: [\"There are three options.\"]\n\n  # ---- triad --------------------------------------------------------------------------------\n  - id: core.triad.001\n    category: triad\n    severity: warn\n    match:\n      kind: regex\n      pattern: '\\b[a-z]{1,12}, [a-z]{1,12},? and [a-z]{1,12}\\b'\n      sentence_exclude: '\\d'\n      sentence_max_words: 25\n    instruction: { action: shorten, text: \"Keep the one that matters, or give evidence for each.\" }\n    examples:\n      hit: [\"It is fast, simple, and reliable.\"]\n      miss: [\"It is fast, simple, and reliable on 3 runners.\"]\n\n  - id: core.triad.002\n    category: triad\n    severity: warn\n    match:\n      kind: regex\n      pattern: '\\bnot (?:just|only|merely|about) .{3,80}?, (?:but|it''s about|it is about)\\b'\n    instruction: { action: rephrase, text: \"State the point directly without the contrast.\" }\n    examples:\n      hit: [\"It's not just about speed, it's about trust.\"]\n      miss: [\"Not only did the test fail, the build did too.\"]\n\n  - id: core.triad.003\n    category: triad\n    severity: info\n    match:\n      kind: any\n      parts:\n        - kind: phrase\n          phrases: [\"whether it's\", \"whether you're\"]\n        - kind: regex\n          pattern: '\\bfrom [a-z]+ to [a-z]+, (?:and )?[a-z]+'\n    instruction: { action: rephrase, text: \"Name the actual case instead of the range.\" }\n    examples:\n      hit: [\"Whether it's a startup or an enterprise…\"]\n      miss: [\"Whether the flag is set decides the path.\"]\n\n  # ---- structure ----------------------------------------------------------------------------\n  - id: core.structure.001\n    category: structure\n    severity: warn\n    match: { kind: document_metric, metric: headers_per_100_words, above: 1.5, min_sentences: 8 }\n    instruction: { action: restructure, text: \"Remove headings; this is short enough to read as prose.\" }\n    examples:\n      hit: [\"<eval corpus ref: core/structure-001-hit-01>\"]\n      miss: [\"<eval corpus ref: core/structure-001-miss-01>\"]\n\n  - id: core.structure.002\n    category: structure\n    severity: warn\n    match: { kind: document_metric, metric: bullet_ratio, above: 0.6, min_sentences: 8, min_item_words: 6 }\n    instruction: { action: restructure, text: \"Rewrite as prose; keep a list only where the items are parallel.\" }\n    examples:\n      hit: [\"<eval corpus ref: core/structure-002-hit-01>\"]\n      miss: [\"<eval corpus ref: core/structure-002-miss-01>\"]\n\n  - id: core.structure.003\n    category: structure\n    severity: warn\n    match: { kind: document_metric, metric: sentence_length_cv, below: 0.25, min_sentences: 10 }\n    instruction: { action: rephrase, text: \"Vary sentence length; combine or split so the rhythm is uneven.\" }\n    examples:\n      hit: [\"<eval corpus ref: core/structure-003-hit-01>\"]\n      miss: [\"<eval corpus ref: core/structure-003-miss-01>\"]\n\n  - id: core.structure.004\n    category: structure\n    severity: block\n    match: { kind: document_metric, metric: closing_similarity, above: 0.6, min_sentences: 6 }\n    instruction: { action: remove, text: \"Remove the closing paragraph; it restates the opening.\" }\n    examples:\n      hit: [\"<eval corpus ref: core/structure-004-hit-01>\"]\n      miss: [\"<eval corpus ref: core/structure-004-miss-01>\"]\n\n  - id: core.structure.005\n    category: structure\n    severity: warn\n    match: { kind: document_metric, metric: bold_per_100_words, above: 3, min_sentences: 6 }\n    instruction: { action: remove, text: \"Remove bold except for the one thing a reader must not miss.\" }\n    examples:\n      hit: [\"<eval corpus ref: core/structure-005-hit-01>\"]\n      miss: [\"<eval corpus ref: core/structure-005-miss-01>\"]\n\n  # ---- repetition ---------------------------------------------------------------------------\n  - id: core.repetition.001\n    category: repetition\n    severity: warn\n    match: { kind: sentence_metric, metric: similarity_to_prior, above: 0.7, min_words: 6 }\n    instruction: { action: merge, text: \"Remove this sentence or merge it with the earlier one that says the same thing.\" }\n    examples:\n      hit: [\"The cache is per tenant. Each tenant has its own cache.\"]\n      miss: [\"<eval corpus ref: core/repetition-001-miss-01>\"]\n";
